insert into public.product_notes (product_id, notes)
select product_id, notes from jsonb_to_recordset($seed$[
  {
    "product_id": "tropic-bar-ultra-12000",
    "notes": "Blue Razz comes from the newest post ('Blue Razz & Litchi Ice, $15 each'); device looks like the Ultra but the caption doesn't say. Confirm."
  },
  {
    "product_id": "life-pod-eco-kit",
    "notes": "Pod in the graphic reads 'Nicotine 4.5%'; caption says 5%. Confirm."
  },
  {
    "product_id": "life-pod-eco-pro-8000",
    "notes": "'Cherry Hulls' copied exactly as written; may be a typo. Confirm. Probably needs the Eco Kit device."
  },
  {
    "product_id": "tropic-bar-blast-8000",
    "notes": "Price is cut off at the edge of the graphic and reads '$8'. Confirm."
  }
]$seed$::jsonb) as x(product_id text, notes text)
on conflict (product_id) do nothing;

